/* PRD 4 layer A: the regional hunt chain and the Rare Target.
 *
 * A won random encounter adds one to the chain of the region the player is in (a world map area plus the server bit,
 * ststatus_map_areas's byte); entering another region, the Guardromon teleport and fighting a Rare Target reset it. The
 * card record keeps the chain with its region (definitive_bestiary.c, REC_EXTRA + 8 and + 9), so a save resumes it.
 *
 * Past DEF_HUNT_CHAIN_MIN wins, each random encounter of a region that has a Rare Target (def_hunt_targets, generated by
 * tools/gen_hunt_targets.py) may be swapped for it: an existing boss battle, fought on the encounter's own stage and
 * music, its enemies raised to the region's level, and the party can always flee from it. The Overlevel Rush never offers to skip it: fieldstg_encounter_start asks here before the Rush.
 *
 * A Rare Target won (layer B) pays DEF_HUNT_XP_MULT times the XP of the encounter it replaced, drops a rare Booster
 * when the battle left no item, and gives its battle's own Hunt Material (the table's), counted in the card record at
 * once and shown on the results screen after the item. The bestiary (layer C) lists under each species the materials of
 * the target battles it fights in.
 *
 * Off in a replay script (def_on): no state changes and no pad_random draw, so the scripts' battles are the emulator's. */
#include "common.h"
#include "pad.h"
#include "records.h"
#include "fieldstg.h"

#include "psxstack/savestate.h"

#include "definitive.h"

extern unsigned char ststatus_map_areas[];
extern int def_on(void); /* port.h declares it under PC_PORT only; the host test builds without it */
extern void port_log(const char *fmt, ...);

static struct {
    signed char from_encounter; /* the battle being set up came from a random encounter */
    signed char rare;           /* and it is the Rare Target */
    short level;                /* the Rare Target's level */
    short base;                 /* the encounter's own battle, the one it replaced (layer B's XP) */
    signed char material;       /* the Rare Target's Hunt Material (layer B) */
} hunt;

/* A Rare Target won, until its results screen ends (layer B). */
static struct {
    signed char pending;  /* a results screen has this reward to show */
    signed char shown;    /* its material's line was shown */
    short base;           /* the battle whose XP it pays DEF_HUNT_XP_MULT times */
    short level;          /* the target's level: the Booster's */
    signed char material; /* the material it gave */
} reward;

static const DefHuntTarget *target_of(int region) {
    int i;

    for (i = 0; i < def_hunt_target_count; i++) {
        if (def_hunt_targets[i].region == region) {
            return &def_hunt_targets[i];
        }
    }
    return NULL;
}

int def_hunt_chance(int chain) {
    int c;

    if (chain < DEF_HUNT_CHAIN_MIN) {
        return 0;
    }
    c = DEF_HUNT_CHANCE_BASE + DEF_HUNT_CHANCE_STEP * (chain - DEF_HUNT_CHAIN_MIN);
    return c > DEF_HUNT_CHANCE_MAX ? DEF_HUNT_CHANCE_MAX : c;
}

void def_hunt_map(int map) {
    int region, chain;

    if (!def_on()) {
        return;
    }
    def_record_hunt(&region, &chain);
    if (ststatus_map_areas[map & 0xFF] != region) {
        if (chain != 0) {
            port_log("hunt: region 0x%X -> 0x%X, chain %d reset", region, ststatus_map_areas[map & 0xFF], chain);
        }
        def_record_set_hunt(ststatus_map_areas[map & 0xFF], 0);
    }
}

void def_hunt_chain_reset(void) {
    int region, chain;

    if (!def_on()) {
        return;
    }
    def_record_hunt(&region, &chain);
    def_record_set_hunt(region, 0);
}

int def_hunt_encounter(int battle) {
    const DefHuntTarget *t;
    int region, chain, chance;

    hunt.from_encounter = 0;
    hunt.rare = 0;
    if (!def_on()) {
        return battle;
    }
    hunt.from_encounter = 1;
    def_record_hunt(&region, &chain);
    t = target_of(region);
    chance = def_hunt_chance(chain);
    if (t == NULL || chance == 0) {
        return battle;
    }
    /* The draw only happens once the feature can act, so a region without a target keeps the encounters' sequence. */
    if ((pad_random.next() & 0x7FFF) % 100 >= chance) {
        return battle;
    }
    hunt.rare = 1;
    hunt.level = t->level;
    hunt.base = (short)battle;
    hunt.material = (signed char)t->material;
    port_log("hunt: chain %d in region 0x%X: the Rare Target (battle %d, level %d)", chain, region, t->battle, t->level);
    return t->battle;
}

void def_hunt_scale(void) {
    int i;

    if (!hunt.rare) {
        return;
    }
    for (i = 0; i < 3; i++) {
        RecordsEnemy *e = &records_state.enemies[i];
        long hp;

        if (e->digimon == 0 || e->level <= 0 || e->level >= hunt.level) {
            continue;
        }
        /* The HP grows with the level; the stats already do through the level (stat_scale is left as it is). */
        hp = (long)e->hp * hunt.level / e->level;
        e->hp = (short)(hp > DEF_HUNT_HP_MAX ? DEF_HUNT_HP_MAX : hp);
        e->level = hunt.level;
    }
}

int def_hunt_active(void) {
    return hunt.rare != 0;
}

void def_hunt_skipped(void) {
    hunt.from_encounter = 0;
    hunt.rare = 0;
}

void def_hunt_battle_end(int result) {
    int region, chain;

    if (hunt.from_encounter && def_on()) {
        def_record_hunt(&region, &chain);
        if (hunt.rare) {
            port_log("hunt: Rare Target %s, chain %d reset", result != 0 ? "won" : "left", chain);
            chain = 0;
            if (result != 0) {
                reward.pending = 1;
                reward.shown = 0;
                reward.base = hunt.base;
                reward.level = hunt.level;
                reward.material = hunt.material;
                def_record_material_add(reward.material, 1); /* in the record now: a save right after keeps it */
                port_log("hunt: material %d (now %d)", reward.material, def_record_material(reward.material));
            }
        } else if (result != 0 && chain < DEF_HUNT_CHAIN_CAP) {
            chain++;
        }
        def_record_set_hunt(region, chain);
    }
    hunt.from_encounter = 0;
    hunt.rare = 0;
}

const unsigned char *def_hunt_material_name(int material) {
    extern const unsigned char def_str_HuntMat0[], def_str_HuntMat1[], def_str_HuntMat2[], def_str_HuntMat3[],
        def_str_HuntMat4[], def_str_HuntMat5[], def_str_HuntMat6[], def_str_HuntMat7[], def_str_HuntMat8[],
        def_str_HuntMat9[], def_str_HuntMat10[], def_str_HuntMat11[], def_str_HuntMat12[], def_str_HuntMat13[],
        def_str_HuntMat14[], def_str_HuntMat15[];
    static const unsigned char *const names[DEF_HUNT_MATERIALS] = {
        def_str_HuntMat0,  def_str_HuntMat1,  def_str_HuntMat2,  def_str_HuntMat3,  def_str_HuntMat4,  def_str_HuntMat5,
        def_str_HuntMat6,  def_str_HuntMat7,  def_str_HuntMat8,  def_str_HuntMat9,  def_str_HuntMat10, def_str_HuntMat11,
        def_str_HuntMat12, def_str_HuntMat13, def_str_HuntMat14, def_str_HuntMat15,
    };

    return names[material < 0 ? 0 : material >= DEF_HUNT_MATERIALS ? DEF_HUNT_MATERIALS - 1 : material];
}

unsigned int def_hunt_species_materials(int species) {
    unsigned int mask = 0;
    int i, k;

    for (i = 0; i < def_hunt_target_count && species != 0; i++) {
        const FieldstgBattle *b = &fieldstg_battles[def_hunt_targets[i].battle];

        for (k = 0; k < 3; k++) { /* an empty slot is fieldstg_battle_enemies[0], species 0 */
            if (b->enemies[k]->digimon == species) {
                mask |= 1u << def_hunt_targets[i].material;
            }
        }
    }
    return mask;
}

int def_hunt_reward_battle(void) {
    return reward.pending ? reward.base : -1;
}

int def_hunt_reward_pack(void) {
    int tier;

    if (!reward.pending) {
        return 0;
    }
    tier = reward.level < 25 ? 0 : 1 + (reward.level - 25) / DEF_HUNT_PACK_LEVELS;
    return DEF_HUNT_PACK_FIRST + (tier > 4 ? 4 : tier);
}

int def_hunt_material_pending(void) {
    return reward.pending && !reward.shown;
}

/* "Hunt material:" <line break> the name, then the wait for a press: ESFGTRPT 11's layout ("Item gained:"). */
const unsigned char *def_hunt_material_text(void) {
    extern const unsigned char def_str_HuntGotPrefix[], def_str_HuntGotSuffix[];
    static unsigned char buf[96];
    const unsigned char *parts[3];
    int i, j, p = 0;

    parts[0] = def_str_HuntGotPrefix;
    parts[1] = def_hunt_material_name(reward.material);
    parts[2] = def_str_HuntGotSuffix;
    for (i = 0; i < 3; i++) {
        for (j = 0; parts[i][j] != 0 && p < (int)sizeof(buf) - 1; j++) {
            buf[p++] = parts[i][j];
        }
    }
    buf[p] = 0;
    reward.shown = 1;
    return buf;
}

void def_hunt_reward_done(void) {
    reward.pending = 0;
    reward.shown = 0;
}

/* Between the swap and the battle's end a save state may be taken (the MCP tests do): it carries whether this is a Rare
 * Target, so a loaded battle still lets the party flee, and a reward its results screen has not shown yet. */
void def_hunt_savestate(struct PortState *s) {
    PORT_STATE_VAR(s, hunt);
    PORT_STATE_VAR(s, reward);
}
